const entrada=$input.first().json;
if(entrada.modo!=='SIMULADO'||entrada.carga.length!==3)throw new Error('Contrato de carga no válido');
const inicio=Date.now(),trazas=[];
const centavos=x=>{if(typeof x!=='number'||!Number.isFinite(x)||x<0||!Number.isSafeInteger(Math.round(x*100))||Math.abs(x*100-Math.round(x*100))>1e-6)throw new Error('Monto inválido');return Math.round(x*100);};
const resultados=entrada.casos.map(c=>{
 const historial=[];let propuesta={...c.propuesta};let esperado=null;
 try{
  if(!c.version_fuente)throw new Error('Falta versión de fuente');
  const inversion=centavos(c.inversion_mxn),saldo=centavos(c.saldo_mxn);
  if(inversion<=0)throw new Error('Inversión no positiva');
  const apoyo=Math.min(Math.floor(inversion/2),saldo);
  esperado={apoyo_mxn:apoyo/100,aportacion_mxn:apoyo/100,inversion_ajustada_mxn:2*apoyo/100,saldo_proyectado_mxn:(saldo-apoyo)/100,requiere_aceptacion_alcance:2*apoyo<inversion,estado:'PENDIENTE_APROBACION',modifica_presupuesto:false};
 }catch(e){historial.push({caso_id:c.caso_id,version:1,ok:false,diagnostico:e.message,costo_api_usd:0});return {caso_id:c.caso_id,distribuidor:c.distribuidor,estado_loop:'ESCALAR',historial};}
 for(let vuelta=1;vuelta<=3;vuelta++){
  if(Date.now()-inicio>10000)throw new Error('Límite temporal de revisión');
  const errores=Object.entries(esperado).filter(([k,v])=>propuesta[k]!==v).map(([k])=>k);
  historial.push({caso_id:c.caso_id,version:vuelta,ok:errores.length===0,diagnostico:errores,costo_api_usd:0});
  if(!errores.length)return {caso_id:c.caso_id,distribuidor:c.distribuidor,estado_loop:'CONVERGIO',propuesta,historial};
  if(vuelta<3)propuesta={...propuesta,...esperado};
 }
 return {caso_id:c.caso_id,estado_loop:'ESCALAR',historial};
});
// Seguridad/costo: transporte de prueba falla dos veces. No se llama una API real.
const usuario='DEMO_AUTORIZADO',permitido='DEMO_AUTORIZADO';let reservado=0,consumo=0;
const presupuesto=250000,eventos=new Set(),recuperacion=[];
let estado='ESCALAR';
for(let intento=1;intento<=3;intento++){
 const evento=String($execution.id)+':'+intento,cota=10000;
 if(usuario!==permitido){estado='NO_AUTORIZADO';break;}
 if(eventos.has(evento)){estado='DUPLICADO';break;}
 if(consumo+reservado+cota>presupuesto){estado='LIMITE_COSTO';break;}
 if(Date.now()-inicio>10000){estado='TIMEOUT';break;}
 eventos.add(evento);reservado+=cota;
 const fallo=intento<3;
 // Transporte local determinista: consumo API comprobable cero; liberar reserva.
 reservado-=cota;const costo_real_micro_usd=0;consumo+=costo_real_micro_usd;
 recuperacion.push({intento,evento,cota_usd:cota/1000000,costo_api_usd:0,estado:fallo?'TIMEOUT_SIMULADO':'OK'});
 if(!fallo){estado='OK';break;}
}
return [{json:{modo:'SIMULADO',alcance:entrada.alcance,carga:entrada.carga,resultados,seguridad_costo:{estado,max_intentos:3,presupuesto_usd:presupuesto/1000000,consumo_api_usd:consumo/1000000,traza:recuperacion},advertencias:['Transporte de prueba local, sin modelos ni APIs externas.','Dedup dentro de esta ejecución; NO demuestra persistencia compartida entre workers.','La prueba no aprueba ni modifica presupuestos operativos.']}}];

const r=$input.first().json;
const validos=r.resultados.filter(c=>c.estado_loop==='CONVERGIO');
if(validos.length!==3||r.resultados[3].estado_loop!=='ESCALAR')throw new Error('Resultados de negocio incorrectos');
if(validos.some(c=>c.historial.length!==2||c.propuesta.modifica_presupuesto!==false))throw new Error('Falta V1/V2 o guardián');
if(r.seguridad_costo.estado!=='OK'||r.seguridad_costo.traza.length!==3||r.seguridad_costo.consumo_api_usd!==0)throw new Error('Loop seguridad/costo incorrecto');
return [{json:{...r,validacion:'PASS',resumen:'3 skills cargados; 3 casos V1->V2; 1 fuente insuficiente; recuperación acotada de 3 intentos; API USD0',ejecucion_n8n:String($execution.id)}}];
